using BeamerPresenter.Application;

namespace BeamerPresenter.TestSupport;

public sealed class RecordingScreenshots : IPresenterScreenshotService
{
    public Exception? Error { get; set; }
    public static readonly byte[] Jpeg = Convert.FromBase64String(
        "");
    public static readonly DateTimeOffset CapturedAt = new(2026, 10, 11, 12, 0, 0, TimeSpan.Zero);
    public Task<PresenterScreenshot> CaptureAsync(CancellationToken cancellationToken = default) =>
        Error is null ? Task.FromResult(new PresenterScreenshot(Jpeg, CapturedAt)) : Task.FromException<PresenterScreenshot>(Error);
}
